create table if not exists public.admin_activity_logs (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),admin_user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text,entity_id uuid,details jsonb not null default '{}'::jsonb); alter table public.admin_activity_logs enable row level security; create index if not exists admin_activity_logs_created_at_idx on public.admin_activity_logs(created_at desc); create index if not exists admin_activity_logs_entity_idx on public.admin_activity_logs(entity_type,entity_id,created_at desc); drop policy if exists "admins can read activity logs" on public.admin_activity_logs; create policy "admins can read activity logs" on public.admin_activity_logs for select to authenticated using ((select public.is_admin())); drop policy if exists "admins can insert activity logs" on public.admin_activity_logs; create policy "admins can insert activity logs" on public.admin_activity_logs for insert to authenticated with check ((select public.is_admin())); alter table public.matches add column if not exists trial_date date; alter table public.matches add column if not exists response_note text;